/* Dịch nghĩa câu đúng và giải thích chi tiết cho từng câu hỏi ngữ pháp.
   Khoá: "id-chủ-đề:id-câu". Giá trị: [bản dịch câu hoàn chỉnh, giải thích chi tiết]. Do AI sinh sẵn một lần. */
window.GRAMMAR_EXPLAIN = window.GRAMMAR_EXPLAIN || {};
Object.assign(window.GRAMMAR_EXPLAIN, {
"to-be:q1": ["Tôi là một học sinh.", "To be có ba dạng: am, is, are. Mỗi chủ ngữ chỉ đi với một dạng nhất định. Riêng I luôn đi với am, không có ngoại lệ, nên I am a student là câu đúng. Hãy nhớ cặp I + am như một cụm cố định."],
"to-be:q2": ["Cô ấy là một bác sĩ.", "Cả she, he và it đều là ngôi thứ ba số ít (chỉ một người hoặc một vật), và cùng đi với is. Cách nhớ: một người khác (không phải tôi, không phải bạn) → is."],
"to-be:q3": ["Họ đang ở nhà.", "They là số nhiều (nhiều người), mà số nhiều và you đều dùng are. Câu này cũng cho thấy to be còn mang nghĩa “ở”: at home = ở nhà."],
"to-be:q4": ["Anh trai tôi cao.", "Gặp một cụm danh từ như my brother, hãy thử thay bằng đại từ: my brother = he. Mà he đi với is. Mẹo này dùng được cho mọi chủ ngữ dài: the teacher = she / he, the cat = it. Câu này không dịch to be, vì tiếng Việt nói “Anh tôi cao”."],
"to-be:q5": ["Chúng tôi là bạn bè.", "We nghĩa là “chúng tôi” (từ hai người trở lên), nên là số nhiều và đi với are. Cùng nhóm với are còn có you và they."],
"to-be:q6": ["Nó là một con mèo.", "It dùng cho vật, con vật hoặc việc không rõ giới tính. It đi với is, giống he và she."],
"to-be:q7": ["Ông ấy không phải là giáo viên của tôi.", "Muốn phủ định, chỉ thêm not sau to be: is not, và nói nhanh là isn't. Không nói He doesn't my teacher, vì doesn't chỉ dùng với động từ thường, không dùng với to be. Dạng amn't không tồn tại trong tiếng Anh."],
"to-be:q8": ["Tôi không đói.", "Với I, phủ định là am not. Khác với is và are, am không có dạng rút gọn isn't hay aren't, nên chỉ viết tắt phía chủ ngữ: I'm not."],
"to-be:q9": ["Bạn có mệt không?", "Để hỏi, đưa to be lên trước chủ ngữ: You are tired → Are you tired? Chủ ngữ là you nên dùng are. Câu hỏi với to be không cần do hay does."],
"to-be:q10": ["Cô ấy có phải là chị gái của bạn không?", "She đi với is. Đưa is lên đầu câu thì thành Is she...? Chữ đầu câu viết hoa: Is."],
"to-be:q11": ["Bạn là học sinh à? Vâng, đúng vậy.", "Câu trả lời ngắn lặp lại chủ ngữ và to be của câu hỏi. Ở dạng khẳng định không được viết tắt, nên nói Yes, I am, không nói Yes, I'm. Viết tắt chỉ dùng ở dạng phủ định (No, I'm not)."],
"to-be:q12": ["Hôm nay trời có lạnh không? Không, không lạnh.", "Câu hỏi bắt đầu bằng Is it, nên câu trả lời ngắn cũng dùng it + is. Phủ định là isn't. Vậy: No, it isn't."],
"to-be:q13": ["Tôi đang vui.", "I'm là cách viết tắt của I am (dấu ' thay chữ a). Dạng I'm happy là câu đúng, còn các lựa chọn kia sai ở chỗ to be không khớp với chủ ngữ I."],
"to-be:q14": ["Tom và tôi học cùng lớp.", "Tom and I là hai người, tương đương we, nên dùng are. Khi có hai chủ ngữ nối bằng and thì luôn xem là số nhiều."],
"to-be:q15": ["Tom và Ben là anh em.", "Hai người (Tom and Ben) tương đương they, số nhiều, nên dùng are. Hai chủ ngữ nối bằng and luôn đi với are."],
"to-be:q16": ["Bố mẹ tôi đang ở chỗ làm.", "Parents (bố và mẹ) là danh từ số nhiều, tương đương they, nên dùng are. Dấu hiệu nhận ra số nhiều: danh từ tận cùng -s."],
"to-be:q17": ["Chìa khoá của bạn có ở trên bàn không?", "Keys là số nhiều (nhiều chiếc), nên to be là are, và đưa lên đầu câu thành Are. Nếu là một chiếc key thì dùng Is your key...?"],
"to-be:q18": ["Cô ấy không phải là y tá.", "Phủ định của to be chỉ thêm not: is not hoặc isn't. Không dùng doesn't, vì doesn't chỉ đi với động từ thường như work, like."],
"to-be:q19": ["Bạn bao nhiêu tuổi?", "Hỏi tuổi trong tiếng Anh dùng to be, không dùng have: How old are you? Trả lời: I am 20 (years old). Sai lầm thường gặp là nói How old do you have."],
"to-be:q20": ["Tom và Anna có ở đây không? Không, họ không có.", "Tom and Anna là hai người = they. Câu trả lời ngắn phủ định của they là aren't (are not). Vậy: No, they aren't."],
"to-be:q21": ["Hôm nay anh ấy không ở trường.", "Phủ định của is là is not, rút gọn isn't. Cả hai đều đúng. Rút gọn thường dùng khi nói."],
"to-be:q22": ["Hôm nay trời nóng.", "Tiếng Anh luôn cần một chủ ngữ. Khi nói về thời tiết, giờ giấc, dùng it làm chủ ngữ giả: It is hot, It is 8 o'clock. Không nói Is hot today (tiếng Việt cho phép bỏ chủ ngữ, tiếng Anh thì không)."],
"present-simple:q1": ["Cô ấy đi học mỗi ngày.", "Hiện tại đơn diễn tả thói quen lặp lại (every day). Với she, he, it, động từ phải thêm -s hoặc -es. Go tận cùng -o nên thêm -es thành goes (cùng nhóm: do → does)."],
"present-simple:q2": ["Họ chơi bóng đá vào các Chủ nhật.", "Với I, you, we, they, động từ giữ nguyên mẫu, không thêm -s. Dấu hiệu on Sundays cho thấy việc lặp lại đều đặn, nên dùng hiện tại đơn."],
"present-simple:q3": ["Bố tôi làm việc ở một ngân hàng.", "My father thay được bằng he, nên động từ thêm -s: work → works. Hiện tại đơn cũng dùng để nói về nghề nghiệp, nơi làm việc."],
"present-simple:q4": ["Anh ấy xem TV mỗi buổi tối.", "Động từ tận cùng -ch, -sh, -s, -x, -z, -o thì thêm -es thay vì -s, vì thêm mỗi -s thì rất khó đọc. Watch + es = watches (đọc là /ˈwɒtʃɪz/)."],
"present-simple:q5": ["Chị tôi học tiếng Anh.", "Động từ tận cùng phụ âm + y thì đổi y thành i rồi thêm -es: study → studies. Chú ý: nếu trước y là nguyên âm (play) thì chỉ thêm -s: plays."],
"present-simple:q6": ["Tom có một gia đình lớn.", "Have là động từ bất quy tắc: với he, she, it, nó không thành haves mà thành has. Với các chủ ngữ còn lại vẫn dùng have."],
"present-simple:q7": ["Tôi không thích cà phê.", "Phủ định ở hiện tại đơn dùng trợ động từ: do not (don't) + động từ nguyên mẫu. Với I, you, we, they dùng don't. Câu trả lời đúng phải có don't, không nói I not like."],
"present-simple:q8": ["Cô ấy không thích trà.", "Với she, he, it dùng doesn't (does not). Điểm quan trọng: doesn't đã chứa chữ -s rồi, nên động từ phía sau giữ nguyên mẫu, không thêm -s nữa: doesn't like."],
"present-simple:q9": ["Anh ấy không sống ở đây.", "Sau doesn't hoặc don't, động từ luôn ở dạng nguyên mẫu. Chữ -s đã nằm ở does rồi, nên không nói He doesn't lives. Quy tắc: chỉ một chỗ trong câu mang dấu hiệu ngôi thứ ba."],
"present-simple:q10": ["Bạn có nói được tiếng Anh không?", "Câu hỏi hiện tại đơn bắt đầu bằng Do hoặc Does + chủ ngữ + động từ nguyên mẫu. You đi với Do. Hỏi về khả năng: Do you speak English? (có biết tiếng Anh không)."],
"present-simple:q11": ["Cô ấy có làm việc ở đây không?", "She đi với Does. Vì Does đã mang -s, động từ work giữ nguyên mẫu. Không nói Does she works."],
"present-simple:q12": ["Cô ấy có thích pizza không?", "Sau Does thì động từ về nguyên mẫu: Does she like...? Nếu thêm -s (likes) là sai vì Does đã gánh phần ngôi thứ ba."],
"present-simple:q13": ["Anh ấy có chơi tennis không? Có, anh ấy có chơi.", "Câu trả lời ngắn lặp lại trợ động từ của câu hỏi, không lặp lại động từ chính. Câu hỏi bắt đầu bằng Does nên trả lời Yes, he does (không nói Yes, he plays)."],
"present-simple:q14": ["Cô ấy làm việc trong một cửa hàng.", "She là ngôi thứ ba số ít nên động từ cần -s: works. Workes là dạng không tồn tại, vì work không tận cùng -ch, -sh, -s, -x nên chỉ thêm -s."],
"present-simple:q15": ["Anh ấy không bao giờ đến muộn.", "Trạng từ tần suất (always, usually, never...) đứng trước động từ thường (I never eat) nhưng đứng sau to be (He is never late). Trong câu này động từ là is nên never đứng sau is."],
"present-simple:q16": ["Mẹ tôi nấu bữa tối mỗi buổi tối.", "My mother thay bằng she, nên động từ thêm -s: cook → cooks. Every evening cho thấy việc lặp lại, nên dùng hiện tại đơn."],
"present-simple:q17": ["Em bé khóc rất nhiều.", "Cry tận cùng phụ âm + y nên đổi y thành i rồi thêm -es: cries. The baby = it/he/she nên động từ thêm -es."],
"present-simple:q18": ["Anh trai bạn có chơi guitar không?", "Your brother thay bằng he, nên trợ động từ là Does. Nhớ: Does đi với he, she, it, còn Do đi với I, you, we, they."],
"present-simple:q19": ["Anh ấy có thích cá không?", "Sau Does động từ giữ nguyên mẫu like. Lựa chọn Does he likes là sai vì chữ -s đã nằm ở Does."],
"present-simple:q20": ["Cô ấy không có xe hơi.", "She đi với doesn't, sau đó là have nguyên mẫu (không phải has). Quy tắc chung: sau does hoặc doesn't thì động từ về nguyên mẫu."],
"present-simple:q21": ["Chúng tôi không đi học vào Chủ nhật.", "We đi với don't (do not), sau đó là động từ nguyên mẫu go. Vậy: We don't go. Cả hai dạng don't go và do not go đều đúng."],
"present-simple:q22": ["Nước sôi ở 100 độ.", "Hiện tại đơn còn diễn tả sự thật hiển nhiên, luôn đúng. Water là it (số ít) nên động từ thêm -s: boils."],
"present-simple:q23": ["Anh ấy thăm ông bà bao lâu một lần?", "How often hỏi tần suất. Trong câu hỏi, chủ ngữ he cần trợ động từ does, và động từ visit giữ nguyên mẫu. Trả lời có thể là every week, once a month..."],
"present-continuous:q1": ["Bây giờ cô ấy đang đọc sách.", "Hiện tại tiếp diễn diễn tả việc đang xảy ra ngay lúc nói (now). Công thức: am / is / are + V-ing. She đi với is nên là is reading."],
"present-continuous:q2": ["Lúc này họ đang chơi bóng đá.", "At the moment = lúc này, là dấu hiệu của hiện tại tiếp diễn. They đi với are, động từ thêm -ing: are playing."],
"present-continuous:q3": ["Tôi đang nghe nhạc.", "Chủ ngữ I đi với am, sau đó là động từ + ing: am listening. Viết tắt thường nói là I'm listening."],
"present-continuous:q4": ["Anh ấy đang pha trà.", "Động từ tận cùng e câm thì bỏ e rồi thêm -ing: make → making, write → writing. He đi với is, nên đáp án là is making."],
"present-continuous:q5": ["Chúng tôi đang chạy trong công viên.", "Từ ngắn một âm tiết kết thúc bằng một nguyên âm + một phụ âm thì gấp đôi phụ âm cuối: run → running, sit → sitting. We đi với are."],
"present-continuous:q6": ["Con mèo đang ngồi trên ghế sofa.", "The cat = it nên dùng is. Sit có kiểu nguyên âm + phụ âm nên gấp đôi t: sitting. Viết sai sitting thành siting là lỗi hay gặp."],
"present-continuous:q7": ["Tôi đang viết một lá thư.", "I đi với am. Write tận cùng e câm nên bỏ e: writing (không phải writeing)."],
"present-continuous:q8": ["Hôm nay cô ấy không đi làm.", "Phủ định hiện tại tiếp diễn thêm not sau to be: is not working = isn't working. Không dùng doesn't, vì đã có to be."],
"present-continuous:q9": ["Tôi không ngủ.", "Với I, phủ định là am not (viết tắt I'm not). Không có dạng amn't hay isn't cho I."],
"present-continuous:q10": ["Bạn có đang nghe không?", "Câu hỏi hiện tại tiếp diễn: đưa to be lên đầu. You đi với are, nên là Are you listening? Không dùng do."],
"present-continuous:q11": ["Anh ấy đang nấu bữa tối à?", "He đi với is. Đưa is lên đầu câu: Is he cooking dinner? Động từ chính giữ nguyên dạng -ing."],
"present-continuous:q12": ["Bạn đang làm gì vậy? Tôi đang làm bài tập về nhà.", "Câu hỏi What are you doing? hỏi việc đang diễn ra, nên trả lời cũng dùng hiện tại tiếp diễn. I đi với am: I am doing."],
"present-continuous:q13": ["Tôi biết câu trả lời.", "Một số động từ chỉ trạng thái (know, like, want, love, understand, need) hầu như không dùng ở dạng tiếp diễn dù đang là hiện tại. Nói I know, không nói I am knowing."],
"present-continuous:q14": ["Cô ấy đang làm một cái bánh.", "Công thức đủ: is + V-ing. Make bỏ e rồi thêm ing: making. Thiếu is hoặc thiếu -ing đều sai."],
"present-continuous:q15": ["Nhìn kìa! Bọn trẻ đang chơi trong vườn.", "Look! và Listen! là dấu hiệu việc đang xảy ra ngay lúc này. Children là số nhiều nên dùng are, rồi playing."],
"present-continuous:q16": ["Cô ấy đang bơi trong hồ bơi.", "Swim kết thúc bằng một nguyên âm + một phụ âm nên gấp đôi m: swimming. Sau is cần V-ing."],
"present-continuous:q17": ["Bây giờ trời có đang mưa không?", "Is it ___ now? có now và is ở trước, nên chỗ trống cần V-ing: raining. Rain + ing, không gấp đôi phụ âm vì có hai nguyên âm (ai)."],
"present-continuous:q18": ["Anh ấy không đang xem TV.", "Phủ định hiện tại tiếp diễn: is + not + V-ing. Không dùng doesn't watching, vì doesn't không đi với V-ing."],
"present-continuous:q19": ["Họ đang nằm trên bãi biển.", "Động từ tận cùng -ie đổi thành -y rồi thêm -ing: lie → lying, die → dying, tie → tying. Đây là trường hợp đặc biệt."],
"present-continuous:q20": ["Tôi muốn một ly cà phê.", "Want là động từ chỉ trạng thái, thường không dùng ở dạng tiếp diễn. Nói I want, không nói I am wanting."],
"present-continuous:q21": ["Bạn đang đi đâu vậy?", "Câu hỏi có từ để hỏi: Where + are + you + V-ing? To be đứng ngay sau từ để hỏi, rồi đến chủ ngữ."],
"present-continuous:q22": ["Cô ấy thường đi bộ đến chỗ làm, nhưng hôm nay cô ấy đi xe buýt.", "Hiện tại đơn (usually walks) nói thói quen, còn today kèm hiện tại tiếp diễn nói việc khác thường đang diễn ra lúc này: is taking. So sánh thói quen với việc đang xảy ra là cách phân biệt hai thì."],
"past-simple:q1": ["Hôm qua tôi đã đến thăm bà tôi.", "Yesterday là mốc thời gian đã qua, nên dùng quá khứ đơn. Visit là động từ có quy tắc: thêm -ed thành visited."],
"past-simple:q2": ["Tối qua cô ấy đã xem một bộ phim.", "Last night là dấu hiệu quá khứ. Động từ có quy tắc thêm -ed: watch → watched. Dạng quá khứ không đổi theo chủ ngữ."],
"past-simple:q3": ["Năm ngoái anh ấy đã học rất chăm.", "Study tận cùng phụ âm + y nên đổi y thành i rồi thêm -ed: studied. Khác với play → played (có nguyên âm trước y)."],
"past-simple:q4": ["Một phút trước chiếc xe đã dừng ở đèn đỏ.", "Stop có kiểu phụ âm + nguyên âm + phụ âm ở từ ngắn nên gấp đôi p rồi thêm -ed: stopped. Tương tự: plan → planned, drop → dropped."],
"past-simple:q5": ["Chúng tôi đã sống ở Huế vào năm 2019.", "Live tận cùng e nên chỉ thêm d: lived. In 2019 là mốc quá khứ cụ thể."],
"past-simple:q6": ["Hôm qua tôi đi học bằng xe buýt.", "Go là động từ bất quy tắc, quá khứ đổi hẳn thành went, không thêm -ed. Loại này phải học thuộc."],
"past-simple:q7": ["Hôm qua họ ăn cơm vào bữa trưa.", "Eat là động từ bất quy tắc: eat – ate – eaten. Ở quá khứ đơn dùng ate. Eaten chỉ dùng với have hoặc has."],
"past-simple:q8": ["Tuần trước cô ấy đã mua một chiếc túi mới.", "Buy là động từ bất quy tắc: buy – bought – bought. Dạng bought dùng cho mọi chủ ngữ."],
"past-simple:q9": ["Tuần trước chúng tôi đã xem một bộ phim hay.", "See – saw – seen. Saw là quá khứ đơn (dùng một mình, có mốc thời gian). Seen là quá khứ phân từ, chỉ dùng sau have hoặc has, ví dụ I have seen it."],
"past-simple:q10": ["Hôm qua tôi không đi học.", "Phủ định quá khứ đơn: didn't + động từ nguyên mẫu. Did không đổi theo chủ ngữ. Không nói didn't went, vì did đã mang nghĩa quá khứ."],
"past-simple:q11": ["Cô ấy đã không gọi cho tôi.", "Sau didn't, động từ ở nguyên mẫu: didn't call (không phải didn't called). Nghĩa quá khứ đã nằm ở did rồi."],
"past-simple:q12": ["Bạn có xem trận đấu không?", "Câu hỏi quá khứ đơn: Did + chủ ngữ + động từ nguyên mẫu. Did dùng cho mọi chủ ngữ, kể cả he, she, it."],
"past-simple:q13": ["Cô ấy có gọi cho bạn không? Có, cô ấy có gọi.", "Câu trả lời ngắn nhắc lại trợ động từ trong câu hỏi: Did... → Yes, she did / No, she didn't."],
"past-simple:q14": ["Hôm qua tôi mệt.", "To be ở quá khứ chỉ có hai dạng: was (I, he, she, it) và were (you, we, they). I đi với was."],
"past-simple:q15": ["Tối qua họ ở nhà.", "They đi với were. Nhớ: were đi với you, we, they (và danh từ số nhiều)."],
"past-simple:q16": ["Tôi đã không đi.", "Đã có didn't mang nghĩa quá khứ nên động từ chính về nguyên mẫu: go. Không nói didn't went. Chỉ một chỗ trong câu mang dấu hiệu quá khứ."],
"past-simple:q17": ["Cô ấy mở cửa và đi vào.", "Quá khứ đơn còn kể các hành động nối tiếp nhau trong quá khứ. Open có quy tắc nên thêm -ed: opened (went là bất quy tắc)."],
"past-simple:q18": ["Chủ nhật tuần trước họ đã chơi tennis.", "Play tận cùng nguyên âm + y, nên giữ nguyên y và thêm -ed: played (không đổi y thành i)."],
"past-simple:q19": ["Tuần trước tôi nhận được một món quà đáng yêu từ dì tôi.", "Get là động từ bất quy tắc: get – got – got (người Anh), got – gotten (người Mỹ). Ở quá khứ đơn dùng got."],
"past-simple:q20": ["Hôm qua anh ấy có đến không?", "Sau Did, động từ về nguyên mẫu: come (không phải came). Did đã mang nghĩa quá khứ."],
"past-simple:q21": ["Sáng hôm qua anh ấy đã không ăn sáng.", "Phủ định quá khứ: didn't + động từ nguyên mẫu. Eat không đổi thành ate sau didn't."],
"past-simple:q22": ["Hôm qua tôi làm mất chìa khoá nên không mở được cửa.", "Lose là động từ bất quy tắc: lose – lost – lost. Chú ý chính tả: lost (không phải losed hay loosed)."],
"past-simple:q23": ["Cuối tuần trước bạn đã đi đâu?", "Last weekend là quá khứ nên câu hỏi dùng did + chủ ngữ + động từ nguyên mẫu (go). Không nói Where did you went."],
"past-simple:q24": ["Tôi đã gặp Lan cách đây hai năm.", "Ago đi sau khoảng thời gian (two years ago) để nói việc xảy ra cách hiện tại bao lâu. Nó là dấu hiệu của quá khứ đơn."],
"future:q1": ["Ngày mai tôi sẽ gọi cho bạn.", "Will + động từ nguyên mẫu dùng để nói về việc sẽ làm, lời hứa, quyết định lúc nói. Will giữ nguyên với mọi chủ ngữ."],
"future:q2": ["Cô ấy sẽ không đến bữa tiệc.", "Phủ định của will là will not, rút gọn won't (không viết willn't). Sau won't là động từ nguyên mẫu."],
"future:q3": ["Ngày mai trời sẽ mưa.", "Will không đổi theo chủ ngữ, nên không có wills. Dùng will để dự đoán dựa trên ý kiến, không có dấu hiệu rõ ràng."],
"future:q4": ["Tuần sau anh ấy sẽ đi Đà Nẵng.", "Sau will là động từ nguyên mẫu không có to: will go. Không nói will goes hay will to go."],
"future:q5": ["Cô ấy sẽ học tiếng Anh.", "Sau will, động từ giữ nguyên mẫu hoàn toàn: will study, không thêm -es dù chủ ngữ là she, và cũng không thêm to."],
"future:q6": ["Ngày mai bạn sẽ đến chứ? Vâng, tôi sẽ đến.", "Câu trả lời Yes, I will cho biết câu hỏi dùng will. Cấu trúc hỏi: Will + chủ ngữ + động từ nguyên mẫu?"],
"future:q7": ["Cuối tuần này tôi sẽ đi thăm dì tôi.", "Be going to nói về kế hoạch đã có từ trước. Công thức: am / is / are going to + động từ. I đi với am."],
"future:q8": ["Cô ấy sẽ học ngành y.", "She đi với is: She is going to study medicine. Be going to cũng dùng cho dự định rõ ràng."],
"future:q9": ["Tháng sau họ sẽ đi du lịch.", "They đi với are: They are going to travel. Hãy chia to be theo chủ ngữ rồi mới đến going to."],
"future:q10": ["Nhìn mây kìa! Trời sắp mưa.", "Khi dự đoán dựa trên dấu hiệu nhìn thấy ngay lúc này (mây đen), dùng be going to. It đi với is nên là is going to."],
"future:q11": ["Ngày mai anh ấy sẽ không đi làm.", "Phủ định be going to: thêm not sau to be. He đi với is nên là isn't going to."],
"future:q12": ["Bạn sắp nấu ăn à? Không, tôi không.", "Câu hỏi dùng be going to thì câu trả lời ngắn dùng chính to be. Với I thì phủ định là am not. Không rút gọn thành amn't."],
"future:q13": ["Cô ấy sẽ đi Đà Nẵng.", "Sau will là động từ nguyên mẫu không có to và không đổi theo ngôi: will go."],
"future:q14": ["Điện thoại đang reo. Để tôi nghe máy.", "Quyết định ngay lúc đang nói (chưa có kế hoạch trước) dùng will. Nếu đã định từ trước thì dùng be going to."],
"future:q15": ["Tôi nghĩ ngày mai trời sẽ nắng.", "Dự đoán theo ý kiến cá nhân (I think...) dùng will + nguyên mẫu. Ở đây chỗ trống cần will để tạo thành will be."],
"future:q16": ["Năm sau cô ấy sẽ 18 tuổi.", "Sau will phải là nguyên mẫu: will be (không phải will is hay will being). Be là nguyên mẫu của am, is, are."],
"future:q17": ["Anh trai tôi sắp mua một chiếc điện thoại mới.", "My brother = he nên dùng is: is going to buy. Công thức đầy đủ: is going to + động từ nguyên mẫu."],
"future:q18": ["Tôi sẽ đi thăm dì tôi.", "Cấu trúc đủ: am going to + động từ nguyên mẫu. Thiếu am hoặc thiếu to đều là lỗi thường gặp."],
"future:q19": ["Tôi đã mua vé rồi. Tối nay chúng tôi sẽ đi xem phim.", "Việc đã chuẩn bị sẵn (đã mua vé) là kế hoạch, nên dùng be going to. We đi với are: are going to."],
"future:q20": ["Ngày mai họ sẽ không đến bữa tiệc.", "Phủ định với will: won't (hoặc will not) + động từ nguyên mẫu come. Won't là dạng đặc biệt, không phải willn't."],
"future:q21": ["Cô ấy sắp chuyển đến Hà Nội phải không?", "Với be going to, câu hỏi đưa to be lên đầu: She is going to → Is she going to...? Không dùng do hay will."],
"future:q22": ["Bạn sẽ giúp tôi chứ?", "Câu hỏi dùng will: Will + chủ ngữ + động từ nguyên mẫu. Đây cũng là cách đưa ra lời nhờ lịch sự."],
"past-continuous:q1": ["Lúc 10 giờ tối qua tôi đang ngủ.", "Quá khứ tiếp diễn nói việc đang diễn ra tại một thời điểm cụ thể trong quá khứ (at 10 last night). Công thức: was / were + V-ing. I đi với was."],
"past-continuous:q2": ["Lúc năm giờ họ đang chơi bóng đá.", "They đi với were: were playing. Quá khứ tiếp diễn dùng was cho I, he, she, it và were cho you, we, they."],
"past-continuous:q3": ["Lúc 8 giờ tối qua cô ấy đang đọc sách.", "She đi với was. Mốc 8 giờ tối qua cho thấy hành động đang diễn ra lúc đó."],
"past-continuous:q4": ["Cô ấy đang đọc một cuốn sách.", "Sau was là V-ing: was reading. Quá khứ tiếp diễn luôn có dạng -ing."],
"past-continuous:q5": ["Họ đang chạy trong công viên.", "Run gấp đôi phụ âm cuối khi thêm -ing: running. Sau were cần V-ing."],
"past-continuous:q6": ["Chúng tôi đã không đang xem TV.", "Phủ định: were + not = weren't, theo sau là V-ing. We đi với were."],
"past-continuous:q7": ["Lúc 8 giờ tối bạn có đang học không?", "You đi với were. Đưa were lên đầu câu hỏi: Were you studying...? Không dùng did."],
});
Object.assign(window.GRAMMAR_EXPLAIN, {
"past-continuous:q8": ["Tôi đang nấu ăn thì điện thoại reo.", "When đứng trước việc ngắn, xảy ra bất ngờ (the phone rang), trong lúc có một việc dài đang diễn ra (was cooking). Hình dung: việc dài là cái nền, việc ngắn là cái cắt ngang."],
"past-continuous:q9": ["Trong lúc cô ấy đang đi bộ thì trời bắt đầu mưa.", "While đi với việc đang kéo dài (was walking). Cách nhớ: while = trong lúc. Mệnh đề sau là việc xen vào: it started to rain."],
"past-continuous:q10": ["Lúc 9 giờ tối qua tôi đang xem phim.", "Mốc giờ cụ thể (at 9 p.m.) và gợi ý “đang xem” cho thấy việc đang diễn ra tại thời điểm đó, nên dùng was watching."],
"past-continuous:q11": ["Tối qua tôi đã xem một bộ phim.", "“Đã xem xong” là việc hoàn tất, không nhấn vào lúc đang diễn ra, nên dùng quá khứ đơn: watched. So sánh với câu trước để thấy hai thì khác nhau ở góc nhìn."],
"past-continuous:q12": ["Họ đang chơi.", "Công thức: were + V-ing với They. Thiếu -ing hoặc dùng was đều sai."],
"past-continuous:q13": ["Lúc 7 giờ tối qua cô ấy đang nấu bữa tối.", "Một mốc giờ cụ thể trong quá khứ + việc đang diễn ra tại đó = quá khứ tiếp diễn. She đi với was."],
"past-continuous:q14": ["Lúc chín giờ chúng tôi đang xem phim.", "Sau were cần V-ing: watching. Không dùng dạng nguyên mẫu hay -ed sau were."],
"past-continuous:q15": ["Lúc bạn gọi, anh ấy có đang ngủ không?", "He đi với was. Đưa was lên đầu câu hỏi: Was he sleeping...? Mệnh đề when you called dùng quá khứ đơn vì là việc ngắn xen vào."],
"past-continuous:q16": ["Tôi đang đi bộ về nhà thì thấy một vụ tai nạn.", "When nối việc đang diễn ra (was walking) với việc xảy ra bất ngờ (saw). Ở đây saw là quá khứ đơn của see."],
"past-continuous:q17": ["Cô ấy đang xem TV thì mất điện.", "Việc dài bị cắt ngang: was watching (quá khứ tiếp diễn), việc ngắn: went out (quá khứ đơn). Chủ ngữ she đi với was."],
"past-continuous:q18": ["Họ đã không đang lắng nghe.", "They đi với weren't (were not) rồi V-ing: weren't listening."],
"past-continuous:q19": ["Lúc 8 giờ tối qua bạn đang làm gì?", "Hỏi việc đang diễn ra tại thời điểm quá khứ: từ để hỏi + were + you + V-ing. You luôn đi với were."],
"past-continuous:q20": ["Tôi đang rửa bát thì làm vỡ một cái ly.", "Việc xen vào, ngắn, dùng quá khứ đơn. Break là bất quy tắc: break – broke – broken, nên dùng broke."],
"modals:q1": ["Cô ấy bơi rất giỏi.", "Động từ khuyết thiếu (can, must, should...) không đổi dạng theo chủ ngữ, nên không có cans. Can + động từ nguyên mẫu diễn tả khả năng."],
"modals:q2": ["Tôi không nghe thấy bạn. Nhạc to quá.", "Phủ định của can là can't (hoặc cannot). Không viết don't can. Đây là cách diễn tả điều không thể làm được."],
"modals:q3": ["Tôi mở cửa sổ được không?", "Can I...? dùng để xin phép. Động từ khuyết thiếu đứng đầu câu hỏi, không cần do. Lịch sự hơn: May I...? hoặc Could I...?"],
"modals:q4": ["Bạn phải đội mũ bảo hiểm. Đó là luật.", "Must diễn tả nghĩa vụ mạnh, bắt buộc, thường do luật lệ hoặc quy định. Sau must là động từ nguyên mẫu."],
"modals:q5": ["Bạn không được đỗ xe ở đây. Việc đó bị cấm.", "Mustn't = cấm, không được phép. Quan trọng: mustn't khác don't have to (không cần). Mustn't là cấm, còn don't have to là không bắt buộc."],
"modals:q6": ["Bạn không cần đến sớm. Lớp học bắt đầu lúc mười giờ.", "Don't have to = không cần, không bắt buộc (đến sớm cũng được, không đến sớm cũng không sao). Khác hẳn mustn't = cấm."],
"modals:q7": ["Trông bạn mệt. Bạn nên đi ngủ sớm.", "Should dùng để khuyên: should + động từ nguyên mẫu. Nó nhẹ hơn must, người nghe có thể không làm."],
"modals:q8": ["Anh ấy không nên ăn nhiều đường như vậy. Nó có hại cho anh ấy.", "Shouldn't = không nên. Dùng để khuyên người khác tránh làm việc có hại."],
"modals:q9": ["Cô ấy có biết lái xe không?", "Sau can chỉ dùng nguyên mẫu: Can she drive? Không thêm -s và không có to, cũng không dùng does."],
"modals:q10": ["Cô ấy biết bơi.", "Can không thêm -s với she (không nói cans), và sau can không có to (không nói can to swim)."],
"modals:q11": ["Cô ấy biết bơi không?", "Với động từ khuyết thiếu, câu hỏi chỉ đảo can lên trước chủ ngữ. Không dùng does và động từ giữ nguyên mẫu."],
"modals:q12": ["“Could you help me, please?” dùng để nhờ giúp một cách lịch sự.", "Could you...? là lời nhờ lịch sự, nhẹ nhàng hơn Can you...? Trong giao tiếp với người lạ, cấp trên, nên ưu tiên Could you."],
"modals:q13": ["Bạn có thể giúp tôi xách cái túi này được không?", "Could you + động từ nguyên mẫu + please là cách nhờ lịch sự. Could ở đây không nói về quá khứ."],
"modals:q14": ["Anh ấy chơi được đàn piano.", "Sau can là động từ nguyên mẫu play (không thêm -s, dù he là ngôi thứ ba)."],
"modals:q15": ["Bạn không nên uống nhiều cà phê như vậy. Nó có hại cho bạn.", "Shouldn't + nguyên mẫu dùng khi khuyên không nên làm. Mạnh hơn nữa là mustn't (cấm)."],
"modals:q16": ["Bạn không được dùng điện thoại ở đây.", "Phủ định của must là mustn't, theo sau là động từ nguyên mẫu không có to. Nghĩa là cấm."],
"modals:q17": ["Bạn phải mặc đồng phục. Đó là quy định.", "Must dùng cho quy định hoặc điều bắt buộc do người nói hoặc luật đặt ra."],
"modals:q18": ["Xin lỗi, tôi không đến bữa tiệc của bạn được. Tôi đang bận.", "Can't dùng khi không thể làm một việc do hoàn cảnh (bận, không có thời gian...)."],
"modals:q19": ["Bạn không cần phải đeo cà vạt. Việc đó không cần thiết.", "Don't have to + nguyên mẫu diễn tả điều không cần thiết (làm cũng được, không làm cũng không sao). Không nhầm với mustn't (cấm)."],
"modals:q20": ["Bạn nên nghỉ ngơi.", "Should = nên, dùng để khuyên bảo. Còn can là có thể hoặc được phép, must là bắt buộc."],
"wh-questions:q1": ["Bạn tên là gì?", "What dùng để hỏi “cái gì”, gồm cả tên, vật, nghề nghiệp. What is your name? là cách hỏi tên quen thuộc."],
"wh-questions:q2": ["Bạn sống ở đâu?", "Where dùng để hỏi nơi chốn. Câu hỏi với động từ thường cần do đứng sau từ để hỏi."],
"wh-questions:q3": ["Người đàn ông kia là ai? Là chú tôi.", "Who dùng để hỏi về người. Câu trả lời nêu quan hệ hoặc tên người (my uncle)."],
"wh-questions:q4": ["Bạn đến lúc mấy giờ? Lúc sáu giờ.", "When hỏi thời điểm. Câu trả lời At six o'clock cho biết thời gian nên dùng When."],
"wh-questions:q5": ["Tại sao bạn đến muộn? Vì xe buýt đến muộn.", "Why hỏi lý do, và câu trả lời bắt đầu bằng Because. Nhìn vào câu trả lời giúp chọn đúng từ để hỏi."],
"wh-questions:q6": ["Bạn bao nhiêu tuổi?", "How đi với tính từ tạo thành cụm hỏi mức độ: How old (tuổi), How tall (cao), How far (xa). Đây là cụm cố định."],
"wh-questions:q7": ["Bạn đến từ đâu?", "Với to be, không cần do: Where + are + you from? Từ để hỏi đứng đầu, to be đứng trước chủ ngữ."],
"wh-questions:q8": ["Cô ấy làm nghề gì?", "What does she do? hỏi nghề nghiệp. She đi với does, và động từ do giữ nguyên mẫu."],
"wh-questions:q9": ["Bạn đến lúc nào?", "Did mang nghĩa quá khứ nên động từ phía sau về nguyên mẫu: arrive, không phải arrived."],
"wh-questions:q10": ["Bạn sống ở đâu?", "Với động từ thường (live), câu hỏi cần trợ động từ do: Where + do + you + live? Thiếu do là lỗi phổ biến."],
"wh-questions:q11": ["Cô ấy muốn gì?", "Sau does, động từ về nguyên mẫu want (không thêm -s). Does đã mang chữ -s của ngôi thứ ba."],
"wh-questions:q12": ["Ai sống ở đây? Anh trai tôi.", "Khi who là chủ ngữ (người làm hành động), không cần do hay does, và động từ chia như ngôi thứ ba: Who lives here? Nếu who là tân ngữ thì cần does: Who does he meet?"],
"wh-questions:q13": ["Sinh nhật bạn là khi nào? Ngày 5 tháng 5.", "When hỏi thời gian. Cụm trả lời on 5 May là ngày tháng nên dùng When."],
"wh-questions:q14": ["Cô ấy đi làm bằng cách nào? Bằng xe buýt.", "How hỏi cách thức, phương tiện. Câu trả lời By bus nói phương tiện nên dùng How."],
"wh-questions:q15": ["Bố mẹ bạn sống ở đâu?", "Your parents là số nhiều (they) nên dùng do. Nếu là your father thì dùng does."],
"wh-questions:q16": ["Cái túi này giá bao nhiêu?", "How much hỏi giá tiền. Với to be: từ để hỏi + is + chủ ngữ. Không thêm do trước khi dùng to be."],
"wh-questions:q17": ["Tại sao bạn học tiếng Anh? Vì tôi muốn đi du lịch.", "Câu trả lời mở đầu bằng Because là câu trả lời cho Why. Do đứng sau chủ ngữ vì có động từ thường study."],
"wh-questions:q18": ["Bộ phim bắt đầu lúc mấy giờ?", "The film = it nên dùng does + động từ nguyên mẫu start. What time hỏi giờ giấc."],
"wh-questions:q19": ["Ai đã làm vỡ cửa sổ?", "Who là chủ ngữ nên không cần did, và động từ chia ở quá khứ trực tiếp: broke. Không nói Who did break."],
"wh-questions:q20": ["Bạn có mấy anh em trai?", "How many + danh từ số nhiều. You đi với do trong câu hỏi hiện tại đơn, và động từ chính have giữ nguyên mẫu."],
"nouns:q1": ["Tôi có hai quyển sách.", "Danh từ số nhiều thông thường thêm -s: book → books. Có số hai thì danh từ phải ở dạng số nhiều."],
"nouns:q2": ["Anh ấy có hai cái hộp.", "Danh từ tận cùng -s, -x, -z, -ch, -sh thêm -es: box → boxes. Lý do: thêm mỗi -s thì rất khó phát âm."],
"nouns:q3": ["Ba em bé đang chơi trong phòng.", "Danh từ tận cùng phụ âm + y đổi y thành i rồi thêm -es: baby → babies. Khác: boy → boys (có nguyên âm trước y)."],
"nouns:q4": ["Bọn trẻ đang ở trong vườn.", "Child → children là số nhiều bất quy tắc, không thêm -s. Cần học thuộc như: man → men, woman → women, foot → feet."],
"nouns:q5": ["Một người đàn ông, hai người đàn ông.", "Man → men là số nhiều bất quy tắc, đổi nguyên âm a thành e."],
"nouns:q6": ["Nhiều người sống ở thành phố này.", "People là số nhiều của person (người). People đã là số nhiều nên không thêm -s: không có peoples trong nghĩa thông thường."],
"nouns:q7": ["Tôi cần một ít nước.", "Water không đếm được nên không dùng a hay số đếm. Dùng some với danh từ không đếm được trong câu khẳng định."],
"nouns:q8": ["Cô ấy có một quả táo.", "A dùng trước âm phụ âm, an dùng trước âm nguyên âm. Apple bắt đầu bằng /æ/ (nguyên âm) nên dùng an."],
"nouns:q9": ["Bạn có sữa không?", "Trong câu hỏi dùng any thay cho some. Milk không đếm được nên không dùng a hay many."],
"nouns:q10": ["Bạn có bao nhiêu quyển sách?", "How many + danh từ đếm được số nhiều (books). Đối với không đếm được, dùng How much."],
"nouns:q11": ["Không còn nhiều nước.", "Much dùng với danh từ không đếm được (water), thường trong câu phủ định và câu hỏi. Nếu là danh từ đếm được thì dùng many."],
"nouns:q12": ["Tôi cần một ít thông tin.", "Information không đếm được, nên không thêm -s và không dùng a, an. Muốn đếm, nói a piece of information. Các từ cùng nhóm: advice, news, furniture, money."],
"nouns:q13": ["Hai người phụ nữ đang băng qua đường.", "Woman → women là số nhiều bất quy tắc. Chú ý phát âm khác nhau: woman /ˈwʊmən/, women /ˈwɪmɪn/."],
"nouns:q14": ["Tôi có ba chiếc đồng hồ đeo tay.", "Tận cùng -ch thì thêm -es: watch → watches. Cùng nhóm: church → churches, box → boxes."],
"nouns:q15": ["Bạn có bao nhiêu tiền?", "Money không đếm được nên dùng How much, không dùng How many."],
"nouns:q16": ["Có nhiều người ở đây.", "People là số nhiều nên đi với are. Many đi với danh từ đếm được số nhiều."],
"nouns:q17": ["Cô ấy cho tôi một lời khuyên hay.", "Advice không đếm được, không dùng a và không thêm -s. Dùng some, hoặc a piece of advice."],
"nouns:q18": ["Tôi cần một ít bánh mì.", "Bread không đếm được, dùng some. Muốn đếm, nói a loaf of bread (một ổ) hoặc a slice of bread (một lát)."],
"nouns:q19": ["Ba chiếc lá rơi từ trên cây xuống.", "Một số danh từ tận cùng -f hoặc -fe đổi f thành v rồi thêm -es: leaf → leaves, knife → knives, wife → wives."],
"nouns:q20": ["Chúng ta không còn trứng. Mua một ít nhé.", "Any dùng trong câu phủ định và câu hỏi. Eggs là danh từ đếm được số nhiều nên đi với any."],
"articles:q1": ["Cô ấy là một bác sĩ.", "Nghề nghiệp cần mạo từ a hoặc an: She is a doctor. Doctor bắt đầu bằng /d/ (phụ âm) nên dùng a."],
"articles:q2": ["Tôi ăn một quả táo mỗi ngày.", "Apple bắt đầu bằng âm nguyên âm /æ/ nên dùng an. Mạo từ phụ thuộc vào âm đầu khi đọc, không phụ thuộc chữ cái."],
"articles:q3": ["Anh ấy đã đợi một tiếng.", "Hour có h câm, đọc là /aʊər/ (bắt đầu bằng nguyên âm), nên dùng an hour. Chọn mạo từ theo âm đọc."],
"articles:q4": ["Đó là một trường đại học.", "University đọc là /ˌjuːnɪˈvɜːsɪti/, bắt đầu bằng âm /j/ (phụ âm) dù viết bằng chữ u. Vì vậy dùng a university."],
"articles:q5": ["Tôi có một con chó. Con chó đó màu nâu.", "Lần đầu nhắc dùng a (a dog). Lần sau, khi người nghe đã biết là con nào, dùng the (the dog)."],
"articles:q6": ["Hôm nay mặt trời rất nóng.", "Chỉ có một mặt trời, ai cũng biết, nên dùng the sun. Tương tự the moon, the Earth, the sky."],
"articles:q7": ["Làm ơn mở cửa ra.", "Khi cả người nói và người nghe đều biết cái cửa nào (cửa trong phòng) thì dùng the."],
"articles:q8": ["Tôi thích âm nhạc.", "Danh từ không đếm được hoặc số nhiều khi nói chung chung thì không dùng mạo từ: I like music, I like dogs."],
"articles:q9": ["Cô ấy chơi bóng đá vào các Chủ nhật.", "Tên môn thể thao (football, tennis) không dùng mạo từ. Nhưng nhạc cụ thì có the: play the guitar."],
"articles:q10": ["Tôi là giáo viên.", "Nói về nghề nghiệp dùng a hoặc an trước danh từ số ít. Không thể bỏ mạo từ: I am teacher là sai."],
"articles:q11": ["Tôi là giáo viên.", "Teacher bắt đầu bằng /t/ (phụ âm) nên dùng a. Không bỏ mạo từ trước danh từ đếm được số ít."],
"articles:q12": ["Cuộc sống thật đẹp.", "Khi nói chung về một khái niệm (life, love, music) thì không dùng mạo từ. The life lại chỉ cuộc sống cụ thể nào đó."],
"articles:q13": ["Ông ấy là một người trung thực.", "Honest có h câm, đọc là /ˈɒnɪst/ (bắt đầu bằng nguyên âm), nên dùng an honest man."],
"articles:q14": ["Tôi cần một cái ô.", "Umbrella đọc bắt đầu bằng nguyên âm /ʌ/, nên dùng an. Mạo từ a, an chỉ dùng trước danh từ đếm được số ít."],
"articles:q15": ["Chị tôi là kỹ sư.", "Engineer bắt đầu bằng nguyên âm /e/ nên dùng an. Nhớ: nghề nghiệp luôn cần a hoặc an."],
"articles:q16": ["Trái Đất quay quanh Mặt Trời.", "Earth và Sun là những vật duy nhất, ai cũng biết, nên đi với the."],
"articles:q17": ["Tối nay trăng sáng.", "Chỉ có một mặt trăng nên dùng the moon."],
"articles:q18": ["Tôi thường ăn sáng lúc 7 giờ.", "Tên các bữa ăn (breakfast, lunch, dinner) thường không dùng mạo từ. Nhưng khi mô tả cụ thể thì dùng: The breakfast was delicious."],
"articles:q19": ["Cô ấy đi học bằng xe buýt.", "Go to school (đi học) và by bus (bằng xe buýt) là cụm cố định, không có mạo từ. Nếu nói to the school thì nghĩa là đến ngôi trường như một nơi chốn."],
"articles:q20": ["Bạn đưa giúp tôi lọ muối được không?", "Cả hai cùng biết lọ muối nào (đang ở trên bàn) nên dùng the. The dùng khi người nghe biết rõ đang nói đến cái gì."],
"pronouns:q1": ["Tôi yêu anh ấy.", "Sau động từ cần đại từ tân ngữ. Tân ngữ của he là him. Bảng: I → me, he → him, she → her, we → us, they → them."],
"pronouns:q2": ["Cô ấy giúp chúng tôi.", "Tân ngữ của we là us. Đứng sau động từ helps nên dùng dạng tân ngữ."],
"pronouns:q3": ["Họ biết cô ấy.", "Tân ngữ của she là her. Her có thể là tân ngữ (know her) hoặc tính từ sở hữu (her book)."],
"pronouns:q4": ["Đây là sách của tôi.", "Trước danh từ (book), dùng tính từ sở hữu: my, your, his, her, our, their. Chúng luôn đi kèm danh từ."],
"pronouns:q5": ["Cuốn sách này là của tôi.", "Khi không còn danh từ phía sau, dùng đại từ sở hữu: mine, yours, his, hers, ours, theirs. Mine thay cho my book."],
"pronouns:q6": ["Cái túi của cô ấy màu đỏ.", "Trước danh từ bag dùng tính từ sở hữu her. Hers (không có danh từ) mới là đại từ sở hữu."],
"pronouns:q7": ["Chiếc xe đó là của họ.", "Không có danh từ phía sau nên dùng đại từ sở hữu: theirs. Their car thì có danh từ."],
"pronouns:q8": ["Đây là xe của Tom.", "Sở hữu của người cụ thể thêm 's: Tom's car. Cũng dùng cho Anna's bag, my father's car."],
"pronouns:q9": ["Kia là những đôi giày của tôi.", "Vật ở xa, số nhiều dùng those. Gần số nhiều: these. Gần số ít: this. Xa số ít: that."],
"pronouns:q10": ["Cái này là gì?", "Vật ở gần, số ít dùng this. Nếu ở xa thì dùng that."],
"pronouns:q11": ["Tôi thích nó.", "Chủ ngữ là I, tân ngữ là it. I đi với like (không thêm -s). Ở đây các lựa chọn khác sai vì dùng sai dạng đại từ làm chủ ngữ hoặc tân ngữ."],
"pronouns:q12": ["Đây là sách của tôi.", "Trước danh từ book dùng my. Mine chỉ dùng khi đứng một mình, và me là dạng tân ngữ nên không đứng trước danh từ."],
"pronouns:q13": ["Anh ấy là bạn tôi. Anh ấy sống ở nhà bên cạnh.", "Làm chủ ngữ (đứng trước động từ) dùng he, she, I, we, they. Him, her, me, us, them chỉ dùng làm tân ngữ."],
"pronouns:q14": ["Bạn giúp tôi được không?", "Tân ngữ sau động từ help là me. Không dùng I sau động từ."],
"pronouns:q15": ["Những chìa khoá này không phải của tôi.", "Không có danh từ phía sau, cần đại từ sở hữu: mine. Còn my keys thì có danh từ."],
"pronouns:q16": ["Nhà của họ lớn.", "Their đứng trước danh từ house. Đừng nhầm với there (ở đó) và they're (they are), phát âm giống nhau."],
"pronouns:q17": ["Cây bút này là của bạn à? Không, không phải của tôi.", "Đứng cuối câu, không còn danh từ, dùng đại từ sở hữu mine thay cho my pen."],
"pronouns:q18": ["Kia là bố mẹ tôi.", "Parents là số nhiều, ở xa nên dùng those. Those are... đi với are."],
"pronouns:q19": ["Cô ấy yêu các con của mình.", "Trước danh từ children cần tính từ sở hữu her. Hers hoặc she đều sai vị trí này."],
"pronouns:q20": ["Cái túi của Lan ở đâu? Nó ở trên ghế.", "Bag là một vật số ít, làm chủ ngữ của câu trả lời nên dùng it. Không dùng They vì chỉ một cái túi."],
"adjectives-adverbs:q1": ["Cô ấy có một ngôi nhà lớn.", "Tính từ bổ nghĩa cho danh từ và đứng trước danh từ: a big house."],
"adjectives-adverbs:q2": ["Họ sống trong hai ngôi nhà lớn.", "Tính từ trong tiếng Anh không đổi dạng theo số nhiều (không có bigs). Chỉ danh từ mới thêm -s."],
"adjectives-adverbs:q3": ["Cô ấy nói chậm.", "Bổ nghĩa cho động từ cần trạng từ, không dùng tính từ. Slow + ly = slowly (cách thức: nói như thế nào)."],
"adjectives-adverbs:q4": ["Anh ấy lái xe cẩn thận.", "Careful (cẩn thận) thêm -ly thành carefully. Chú ý chính tả: giữ chữ l cuối của careful và thêm ly, nên có hai chữ l."],
"adjectives-adverbs:q5": ["Cô ấy hát hay.", "Good là tính từ, còn trạng từ tương ứng là well. Nói She sings well, không nói She sings goodly."],
"adjectives-adverbs:q6": ["Mỗi ngày anh ấy làm việc chăm chỉ.", "Hard vừa là tính từ vừa là trạng từ. Hardly nghĩa khác: hầu như không (He hardly works = anh ấy hầu như không làm)."],
"adjectives-adverbs:q7": ["Anh ấy chạy nhanh.", "Fast vừa là tính từ (a fast car) vừa là trạng từ (runs fast). Không có fastly."],
});
Object.assign(window.GRAMMAR_EXPLAIN, {
"adjectives-adverbs:q8": ["Cô ấy vui. Cô ấy mỉm cười một cách vui vẻ.", "Trạng từ cách thức = tính từ + ly. Tính từ tận cùng y thì đổi y thành i rồi thêm ly: happy → happily, easy → easily."],
"adjectives-adverbs:q9": ["Hôm nay trời rất lạnh.", "Very là trạng từ chỉ mức độ, đứng trước tính từ (cold) để nhấn mạnh: very cold. Không dùng very trước động từ."],
"adjectives-adverbs:q10": ["Cô ấy nói chậm.", "Slowly là trạng từ nên bổ nghĩa cho động từ speaks. Tính từ slow chỉ dùng cho danh từ (a slow car)."],
"adjectives-adverbs:q11": ["Một ngôi nhà lớn.", "Trong tiếng Anh, tính từ đứng trước danh từ (big house), ngược với tiếng Việt (nhà lớn)."],
"adjectives-adverbs:q12": ["Quickly (một cách nhanh chóng) là trạng từ.", "Trạng từ cách thức thường tạo bằng tính từ + ly: quick → quickly. Tính từ quick nghĩa là nhanh, dùng cho danh từ."],
"adjectives-adverbs:q13": ["Món súp nóng.", "Sau to be (is) dùng tính từ để mô tả chủ ngữ: The soup is hot. Không dùng trạng từ hotly."],
"adjectives-adverbs:q14": ["Anh ấy là người chạy nhanh. Anh ấy chạy nhanh.", "Quick là tính từ (a quick runner), còn bổ nghĩa cho động từ runs cần trạng từ quickly."],
"adjectives-adverbs:q15": ["Cô ấy là người lái xe cẩn thận.", "Driver là danh từ nên cần tính từ careful đứng trước. Trạng từ carefully chỉ dùng khi bổ nghĩa cho động từ."],
"adjectives-adverbs:q16": ["Anh ấy làm việc chăm chỉ.", "Hard là cả tính từ và trạng từ. Không thêm -ly: hardly có nghĩa khác (hầu như không)."],
"adjectives-adverbs:q17": ["Cô ấy đến họp muộn.", "Late vừa là tính từ (a late bus) vừa là trạng từ (arrived late). Lately nghĩa là gần đây, không phải muộn."],
"adjectives-adverbs:q18": ["Cô ấy là một ca sĩ rất giỏi.", "Singer là danh từ nên cần tính từ good. Very là trạng từ bổ nghĩa cho good. Singer đếm được số ít nên cần a."],
"adjectives-adverbs:q19": ["Anh ấy nói tiếng Anh giỏi.", "Bổ nghĩa cho động từ speaks cần trạng từ. Trạng từ của good là well (không phải goodly)."],
"adjectives-adverbs:q20": ["Bài kiểm tra cực kỳ dễ. Tôi làm xong trong mười phút.", "Extremely là trạng từ chỉ mức độ, bổ nghĩa cho tính từ easy. Ý là rất rất dễ."],
"comparison:q1": ["Tom cao hơn Ben.", "So sánh hơn của tính từ ngắn (một âm tiết): thêm -er rồi dùng than. Công thức: A + to be + tính từ-er + than + B."],
"comparison:q2": ["Quyển sách này thú vị hơn quyển kia.", "Tính từ dài (từ hai âm tiết trở lên, như interesting) dùng more + tính từ + than, không thêm -er."],
"comparison:q3": ["Cô ấy là cô gái cao nhất lớp.", "So sánh nhất của tính từ ngắn: the + tính từ-est. So sánh nhất luôn có the và dùng để so một người với cả nhóm."],
"comparison:q4": ["Đây là chiếc đồng hồ đắt nhất.", "So sánh nhất của tính từ dài: the most + tính từ. Expensive có ba âm tiết nên dùng most."],
"comparison:q5": ["Hôm nay đẹp trời hơn hôm qua.", "Nice đã tận cùng e nên chỉ thêm r: nicer (không viết nicee hay niceer). Tương tự: large → larger."],
"comparison:q6": ["Anh ấy vui hơn anh trai mình.", "Happy tận cùng phụ âm + y nên đổi y thành i rồi thêm -er: happier. Tương tự: easy → easier."],
"comparison:q7": ["Hôm nay nóng hơn hôm qua.", "Hot có dạng phụ âm + nguyên âm + phụ âm nên gấp đôi t: hotter. Tương tự: big → bigger."],
"comparison:q8": ["Cái bánh pizza này ngon hơn cái kia.", "Good là tính từ bất quy tắc: good → better → best. Không nói gooder."],
"comparison:q9": ["Đây là cái pizza ngon nhất trong thành phố.", "Bậc nhất của good là the best. Nhớ có the."],
"comparison:q10": ["Tiếng Anh của anh ấy tệ hơn của tôi.", "Bad cũng bất quy tắc: bad → worse → worst. Không nói badder."],
"comparison:q11": ["Cô ấy cao bằng tôi.", "So sánh bằng: as + tính từ nguyên dạng + as. Giữ tính từ ở dạng gốc, không thêm -er."],
"comparison:q12": ["Cô ấy cao hơn tôi.", "Tính từ ngắn chỉ thêm -er, không thêm more. Dùng cả hai (more taller) là sai."],
"comparison:q13": ["Mai trẻ hơn Lan.", "Young có một âm tiết nên thêm -er: younger."],
"comparison:q14": ["Đây là ngôi nhà lớn nhất trên phố.", "Big gấp đôi g rồi thêm -est: biggest. Bậc nhất đi với the."],
"comparison:q15": ["Với tôi, tiếng Anh dễ hơn môn Toán.", "Easy tận cùng phụ âm + y nên đổi y thành i rồi thêm -er: easier."],
"comparison:q16": ["Đây là ngày tuyệt nhất đời tôi.", "Bậc nhất của good là the best. Nhớ phân biệt: better dùng khi so hai đối tượng, best khi so trong nhóm."],
"comparison:q17": ["Đi máy bay đắt hơn đi xe buýt.", "Expensive là tính từ dài nên dùng more expensive than. Không thêm -er vào tính từ dài."],
"comparison:q18": ["Cô ấy không cao bằng chị mình.", "Phủ định của so sánh bằng: not as + tính từ nguyên dạng + as. Nghĩa: thấp hơn một chút."],
"comparison:q19": ["Tháng nào ngắn nhất trong năm?", "Short là tính từ ngắn nên so sánh nhất: the shortest. Đáp án là February (tháng Hai)."],
"comparison:q20": ["Thời tiết hôm nay tệ hơn hôm qua.", "So sánh hơn của bad là worse (bất quy tắc)."],
"prepositions:q1": ["Lớp học bắt đầu lúc 8 giờ.", "At dùng cho giờ giấc cụ thể (at 8 o'clock, at noon, at night). Hình dung: một điểm trên đồng hồ."],
"prepositions:q2": ["Tôi sinh ngày 5 tháng 5.", "On dùng cho ngày (on 5 May), thứ (on Monday), ngày lễ cụ thể (on Christmas Day)."],
"prepositions:q3": ["Chúng tôi đi du lịch vào mùa hè.", "In dùng cho khoảng thời gian dài: tháng, năm, mùa, thế kỷ (in summer, in May, in 2020)."],
"prepositions:q4": ["Tôi có một cuộc họp vào thứ Hai.", "Thứ trong tuần đi với on: on Monday, on Friday morning."],
"prepositions:q5": ["Tôi thức dậy vào buổi sáng.", "Buổi trong ngày dùng in: in the morning, in the afternoon, in the evening. Ngoại lệ: at night."],
"prepositions:q6": ["Chìa khoá ở trên bàn.", "On dùng khi vật tiếp xúc, nằm trên bề mặt. Ở trên nhưng không chạm thì dùng above hoặc over."],
"prepositions:q7": ["Cô ấy sống ở Hà Nội.", "In dùng cho nơi chốn lớn: thành phố, quốc gia (in Hanoi, in Vietnam)."],
"prepositions:q8": ["Anh ấy đang đợi ở trạm xe buýt.", "At dùng cho một điểm cụ thể (at the bus stop, at the door, at school)."],
"prepositions:q9": ["Tôi đi học bằng xe buýt.", "Phương tiện đi lại dùng by: by bus, by car, by train. Đi bộ là on foot."],
"prepositions:q10": ["Ngân hàng nằm cạnh trường học.", "Next to = bên cạnh, sát bên. Tương tự near (gần) và beside."],
"prepositions:q11": ["Con mèo ở dưới cái ghế.", "Under = bên dưới. Trái nghĩa là on top of hoặc above."],
"prepositions:q12": ["Tôi có tiết học vào thứ Hai.", "Thứ trong tuần dùng on, không dùng in hay at."],
"prepositions:q13": ["Chúng tôi ăn tối lúc 7 giờ tối.", "At dùng cho giờ chính xác: at 7 p.m."],
"prepositions:q14": ["Sinh nhật tôi vào tháng Ba.", "Tháng đi với in: in March. Ngày cụ thể của tháng đi với on: on 5 March."],
"prepositions:q15": ["Bức tranh ở trên tường.", "Treo hoặc dính trên bề mặt tường dùng on the wall (không dùng in)."],
"prepositions:q16": ["Tôi ở nhà vào ban đêm.", "At home và at night là cụm cố định, phải nhớ nguyên cụm, không thay at bằng in hay on."],
"prepositions:q17": ["Hôm qua cô ấy đã đến Huế.", "Arrive in dùng với thành phố, quốc gia. Arrive at dùng cho nơi nhỏ hơn (at the airport, at the station)."],
"prepositions:q18": ["Con mèo ở sau ghế sofa.", "Behind đã là giới từ hoàn chỉnh, đi thẳng với danh từ, không thêm of hay in."],
"prepositions:q19": ["Tôi sinh năm 2005.", "Năm dùng in: in 2005. Tháng, mùa, năm, thế kỷ đều dùng in."],
"prepositions:q20": ["Anh ấy giỏi môn toán.", "Good at + môn học hoặc kỹ năng là cụm cố định. Tương tự bad at, interested in, afraid of."],
"there-is:q1": ["Có một quyển sách ở trên bàn.", "There is + danh từ số ít. There is dùng để nói “có” cái gì ở một nơi nào đó."],
"there-is:q2": ["Có ba học sinh trong phòng.", "There are + danh từ số nhiều. Hãy nhìn danh từ phía sau để chọn is hay are, không phụ thuộc vào there."],
"there-is:q3": ["Có một ít sữa trong tủ lạnh.", "Danh từ không đếm được (milk, water, rice) luôn dùng is: There is some milk."],
"there-is:q4": ["Gần đây không có ngân hàng nào.", "Phủ định của there is là there isn't. A bank là số ít nên dùng isn't."],
"there-is:q5": ["Ở đây có cửa hàng nào không?", "Shops là số nhiều nên câu hỏi là Are there any...? Dùng any trong câu hỏi."],
"there-is:q6": ["Có công viên không? Có.", "Trả lời ngắn lặp lại there + to be: Yes, there is. / No, there isn't."],
"there-is:q7": ["Tôi có một chiếc xe hơi.", "Have got = have (có), dùng nhiều trong tiếng Anh Anh. I, you, we, they đi với have got."],
"there-is:q8": ["Cô ấy có hai anh em trai.", "She, he, it đi với has got. Has là dạng của have với ngôi thứ ba số ít."],
"there-is:q9": ["Bạn có bút không? Không, tôi không có.", "Trả lời ngắn lặp lại have: No, I haven't. Không cần lặp lại got."],
"there-is:q10": ["Anh ấy không có con chó.", "Phủ định của has got: hasn't got hoặc has not got. Không dùng doesn't have got."],
"there-is:q11": ["Có hai quyển sách.", "Two books là số nhiều nên There are. Chú ý: There is two books là lỗi hay gặp."],
"there-is:q12": ["Cô ấy có một chiếc xe đạp.", "She đi với has got. Câu này nói về sở hữu."],
"there-is:q13": ["Có một quả táo ở trên bàn.", "An apple là số ít nên dùng There is."],
"there-is:q14": ["Trong tủ lạnh không có quả trứng nào.", "Eggs là số nhiều nên phủ định là There aren't any eggs."],
"there-is:q15": ["Gần đây có bưu điện không?", "A post office là số ít nên câu hỏi là Is there a...?"],
"there-is:q16": ["Có một ít nước trong ly.", "Water không đếm được nên dùng There is some water."],
"there-is:q17": ["Bạn có bút không? Có, tôi có.", "Trả lời ngắn khẳng định lặp lại have: Yes, I have."],
"there-is:q18": ["Chúng tôi không có tiền.", "We đi với haven't got. Any dùng trong câu phủ định: haven't got any money."],
"there-is:q19": ["Thị trấn của bạn có rạp chiếu phim không?", "A cinema là số ít nên dùng Is there a cinema...?"],
"there-is:q20": ["Lớp bạn có bao nhiêu học sinh?", "Students là số nhiều nên dùng are: How many + danh từ số nhiều + are there?"],
"conditionals:q1": ["Nếu bạn làm nóng đá, nó tan chảy.", "Câu điều kiện loại 0 nói về sự thật luôn đúng: if + hiện tại đơn, hiện tại đơn. Ice là it nên melt thêm -s: melts."],
"conditionals:q2": ["Nếu ngày mai trời mưa, chúng tôi sẽ ở nhà.", "Điều kiện loại 1 nói về khả năng có thật ở tương lai: if + hiện tại đơn, will + động từ nguyên mẫu."],
"conditionals:q3": ["Nếu bạn học chăm chỉ, bạn sẽ đỗ kỳ thi.", "Loại 1: vế kết quả dùng will + nguyên mẫu. Pass là động từ nguyên mẫu nên will pass."],
"conditionals:q4": ["Nếu trời mưa, tôi sẽ mang theo ô.", "Sau will là động từ nguyên mẫu take, không có to và không thêm -s."],
"conditionals:q5": ["Nếu ngày mai trời mưa, chúng tôi sẽ ở nhà.", "Quy tắc quan trọng: sau if dùng hiện tại đơn dù nói về tương lai. Không nói If it will rain. It là ngôi thứ ba nên rain thêm -s."],
"conditionals:q6": ["Nếu tôi có thời gian, tôi sẽ gọi cho bạn.", "Vế if dùng hiện tại đơn: have (I đi với have, không phải will have)."],
"conditionals:q7": ["Nếu bạn không nhanh lên, bạn sẽ bị muộn.", "Vế kết quả ở tương lai dùng will + nguyên mẫu: will be. Vế if dùng hiện tại phủ định don't hurry."],
"conditionals:q8": ["Nếu bạn không nhanh lên, bạn sẽ bị muộn.", "Unless = if ... not, và tự nó đã mang nghĩa phủ định. Unless you hurry = If you don't hurry. Không nói unless you don't hurry."],
"conditionals:q9": ["Nếu có thời gian, tôi sẽ gọi cho bạn.", "If nghĩa là nếu, nêu điều kiện để việc ở vế kia xảy ra."],
"conditionals:q10": ["Nếu trời mưa, tôi sẽ ở nhà.", "Loại 1: if + hiện tại đơn, will + nguyên mẫu. Các lựa chọn sai thường để will hoặc quá khứ trong vế if."],
"conditionals:q11": ["Nếu tôi gặp anh ấy, tôi sẽ nói với anh ấy.", "Vế if: hiện tại đơn (see). Vế kết quả: will tell. Không dùng will see trong vế if."],
"conditionals:q12": ["Mệnh đề if dùng hiện tại đơn.", "Quy tắc loại 1: if + hiện tại đơn, will + nguyên mẫu. Dùng hiện tại đơn dù nói về tương lai."],
"conditionals:q13": ["Nếu bạn trộn xanh dương với vàng, bạn được màu xanh lá.", "Sự thật khoa học, luôn đúng: hiện tại đơn ở cả hai vế (you get)."],
"conditionals:q14": ["Nếu cô ấy đến, chúng ta sẽ bắt đầu cuộc họp.", "Vế if dùng hiện tại đơn, và she thêm -s: comes. Vế kết quả dùng will start."],
"conditionals:q15": ["Chúng ta sẽ đi picnic nếu trời không mưa.", "Vế if dùng hiện tại đơn: isn't rainy. Không dùng won't be rainy."],
"conditionals:q16": ["Nếu bạn không học, bạn sẽ trượt.", "Vế if có thể phủ định: don't study (hiện tại đơn). Vế kết quả: will fail."],
"conditionals:q17": ["Bạn sẽ lỡ tàu nếu bạn không đi ngay.", "Unless you leave now = if you don't leave now. Unless đã mang nghĩa phủ định nên động từ phía sau ở dạng khẳng định."],
"conditionals:q18": ["Nếu ngày mai trời nắng, chúng ta sẽ đi biển.", "Vế if dùng hiện tại đơn: is, không phải will be. Tomorrow nói về tương lai nhưng vẫn dùng hiện tại sau if."],
"conditionals:q19": ["Nếu tôi gặp anh ấy, tôi sẽ chuyển lời nhắn của bạn.", "Sau if dùng hiện tại đơn: see (I đi với see). Không dùng will see."],
"conditionals:q20": ["Nếu bạn làm rơi một cái ly, nó vỡ.", "Đây là sự thật luôn đúng nên dùng loại 0: hiện tại đơn ở cả hai vế (drop, breaks). Không dùng will."],
"passive:q1": ["Tiếng Anh được nói ở nhiều quốc gia.", "Bị động nhấn vào đối tượng chịu tác động. Công thức: be + V3. Hiện tại đơn: is / are + V3. English là số ít nên is spoken."],
"passive:q2": ["Cửa sổ bị một cậu bé làm vỡ hôm qua.", "Yesterday là quá khứ, nên dùng was / were + V3. Window là số ít: was broken. By a boy là người làm."],
"passive:q3": ["Lúa gạo được nông dân trồng ở Việt Nam.", "Hiện tại đơn bị động: is / are + V3. Rice không đếm được nên đi với is: is grown."],
"passive:q4": ["Ngôi nhà này được xây năm 1990.", "In 1990 là mốc quá khứ nên dùng was built. Người xây không quan trọng nên không cần by."],
"passive:q5": ["Những bức thư này do Anna viết.", "Letters là số nhiều nên dùng were + V3 ở quá khứ: were written."],
"passive:q6": ["Cây cầu được xây năm 1995.", "V3 của build là built (bất quy tắc: build – built – built)."],
"passive:q7": ["Chiếc bánh do mẹ tôi làm.", "V3 của make là made (make – made – made)."],
"passive:q8": ["Lá thư do Tom viết.", "V3 của write là written (write – wrote – written). Không dùng wrote trong bị động."],
"passive:q9": ["Tom viết lá thư → Lá thư được Tom viết.", "Khi chuyển sang bị động, giữ nguyên thì của câu gốc: writes (hiện tại đơn) thì bị động là is written. Tân ngữ của câu chủ động (the letter) thành chủ ngữ."],
"passive:q10": ["Cửa sổ không bị Tom làm vỡ.", "Phủ định bị động quá khứ: was not (wasn't) + V3. Chủ ngữ số ít (the window) nên dùng wasn't."],
"passive:q11": ["Ngôi nhà này được xây năm 1990 phải không?", "Câu hỏi bị động: đưa be lên đầu: Was + chủ ngữ + V3? This house số ít nên dùng Was."],
"passive:q12": ["Ngôi nhà được xây vào năm 1990.", "Bị động bắt buộc phải có be + V3. Thiếu was hoặc dùng sai dạng động từ là lỗi hay gặp."],
"passive:q13": ["Ô tô được sản xuất ở nhà máy này.", "Cars là số nhiều, hiện tại đơn bị động: are + V3 (are made)."],
"passive:q14": ["Bộ phim đã được hàng triệu người xem.", "V3 của see là seen (see – saw – seen). Chú ý phân biệt với saw (quá khứ đơn)."],
"passive:q15": ["Email này được sếp của tôi gửi hôm qua.", "Yesterday là quá khứ nên dùng was + V3. Send là bất quy tắc: send – sent – sent."],
"passive:q16": ["Cuốn sách được một sinh viên viết.", "Bị động quá khứ: was + V3. V3 của write là written."],
"passive:q17": ["Họ dọn phòng mỗi ngày → Phòng được dọn mỗi ngày.", "Câu chủ động ở hiện tại đơn (clean) nên bị động là is + V3: is cleaned. Không cần by they vì không quan trọng."],
"passive:q18": ["Anna viết lá thư này → Lá thư này do Anna viết.", "Câu chủ động ở quá khứ đơn (wrote) nên bị động là was + V3: was written."],
"passive:q19": ["Những chiếc bánh này do mẹ bạn làm phải không?", "Cakes là số nhiều, hiện tại đơn: Are + chủ ngữ + V3? Câu hỏi bị động chỉ đảo be lên đầu."],
"passive:q20": ["Những cửa sổ đã không được lau hôm qua.", "Windows là số nhiều, quá khứ nên dùng weren't + V3. Phủ định chỉ thêm not sau be."]
});
